package com.nigson.experience.careers;
import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;
/** Purpose-separated, resource-bound applicant encryption and keyed email lookup fingerprint. */
public final class CareerSecrets {
 private final int hashVersion;private final byte[] hash;private final String active;private final Map<String,byte[]> encryption;private final SecureRandom random=new SecureRandom();
 public CareerSecrets(int hashVersion,byte[] hash,String active,Map<String,byte[]> encryption){if(hashVersion<1||hash==null||hash.length!=32||active==null||!active.matches("[A-Za-z0-9_-]{1,40}")||encryption==null||encryption.isEmpty()||encryption.size()>3||!encryption.containsKey(active))throw new IllegalArgumentException("CAREER_KEY_POLICY_REQUIRED");var copy=new HashMap<String,byte[]>();encryption.forEach((k,v)->{if(k==null||!k.matches("[A-Za-z0-9_-]{1,40}")||v==null||v.length!=32||MessageDigest.isEqual(hash,v))throw new IllegalArgumentException("CAREER_KEY_POLICY_REQUIRED");copy.put(k,v.clone());});this.hashVersion=hashVersion;this.hash=hash.clone();this.active=active;this.encryption=Map.copyOf(copy);}
 public byte[] encrypt(UUID id,String value){try{byte[] nonce=new byte[12];random.nextBytes(nonce);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(encryption.get(active),"AES"),new GCMParameterSpec(128,nonce));c.updateAAD(aad(active,id));byte[] body=c.doFinal(value.getBytes(StandardCharsets.UTF_8));return ("NIGCAREER1."+active+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(nonce)+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(body)).getBytes(StandardCharsets.US_ASCII);}catch(Exception e){throw new IllegalStateException("CAREER_ENCRYPTION_FAILED");}}
 public String decrypt(UUID id,byte[] value){try{if(value==null||value.length>2048)throw new IllegalArgumentException();String[] p=new String(value,StandardCharsets.US_ASCII).split("\\.",-1);if(p.length!=4||!"NIGCAREER1".equals(p[0])||!encryption.containsKey(p[1]))throw new IllegalArgumentException();byte[] nonce=Base64.getUrlDecoder().decode(p[2]);if(nonce.length!=12)throw new IllegalArgumentException();Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(encryption.get(p[1]),"AES"),new GCMParameterSpec(128,nonce));c.updateAAD(aad(p[1],id));return new String(c.doFinal(Base64.getUrlDecoder().decode(p[3])),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("CAREER_DECRYPTION_FAILED");}}
 public String uploadToken(){byte[] value=new byte[32];random.nextBytes(value);return Base64.getUrlEncoder().withoutPadding().encodeToString(value);}
 public byte[] encryptUploadToken(UUID id,String token){try{if(id==null||id.equals(new UUID(0,0))||token==null||Base64.getUrlDecoder().decode(token).length!=32)throw new IllegalArgumentException();byte[] nonce=new byte[12];random.nextBytes(nonce);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(encryption.get(active),"AES"),new GCMParameterSpec(128,nonce));c.updateAAD(uploadAad(active,id));byte[] body=c.doFinal(token.getBytes(StandardCharsets.US_ASCII));return ("NIGCAREER1."+active+".UPLOAD_TOKEN."+Base64.getUrlEncoder().withoutPadding().encodeToString(nonce)+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(body)).getBytes(StandardCharsets.US_ASCII);}catch(Exception e){throw new IllegalStateException("CAREER_TOKEN_ENCRYPTION_FAILED");}}
 public String decryptUploadToken(UUID id,byte[] value){try{if(id==null||id.equals(new UUID(0,0))||value==null||value.length>2048)throw new IllegalArgumentException();String[] p=new String(value,StandardCharsets.US_ASCII).split("\\.",-1);if(p.length!=5||!"NIGCAREER1".equals(p[0])||!"UPLOAD_TOKEN".equals(p[2])||!encryption.containsKey(p[1]))throw new IllegalArgumentException();byte[] nonce=Base64.getUrlDecoder().decode(p[3]);if(nonce.length!=12)throw new IllegalArgumentException();Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(encryption.get(p[1]),"AES"),new GCMParameterSpec(128,nonce));c.updateAAD(uploadAad(p[1],id));String token=new String(c.doFinal(Base64.getUrlDecoder().decode(p[4])),StandardCharsets.US_ASCII);if(Base64.getUrlDecoder().decode(token).length!=32)throw new IllegalArgumentException();return token;}catch(Exception e){throw new IllegalStateException("CAREER_TOKEN_DECRYPTION_FAILED");}}
 private static byte[] aad(String key,UUID id){if(id==null||id.equals(new UUID(0,0)))throw new IllegalArgumentException("CAREER_SECRET_REJECTED");return ("NIGCAREER1:"+key+":"+id+":EMAIL").getBytes(StandardCharsets.US_ASCII);}
 private static byte[] uploadAad(String key,UUID id){return ("NIGCAREER1:"+key+":"+id+":UPLOAD_TOKEN").getBytes(StandardCharsets.US_ASCII);}
 public String fingerprint(String value){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(hash,"HmacSHA256"));return HexFormat.of().formatHex(m.doFinal(("CAREER_EMAIL:"+hashVersion+":"+value.strip().toLowerCase(Locale.ROOT)).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("CAREER_HASH_FAILED");}}
 @Override public String toString(){return "CareerSecrets[protected]";}
}
